Fixes: ff462551235d ("Input: uinput - switch to the new FF interface")
Cc: stable@vger.kernel.org
Link: https://lore.kernel.org/all/CABXGCsMoxag+kEwHhb7KqhuyxfmGGd0P=tHZyb1uKE0pLr8Hkg@mail.gmail.com/
Signed-off-by: Mikhail Gavrilov <mikhail.v.gavrilov@gmail.com>
Link: https://patch.msgid.link/20260407075031.38351-1-mikhail.v.gavrilov@gmail.com
Signed-off-by: Dmitry Torokhov <dmitry.torokhov@gmail.com>

Here is the root cause:
The function `uinput_request_send()` in the uinput driver acquired `udev->mutex` while the caller already held `ff->mutex`, creating a circular lock dependency chain (`ff->mutex -> udev->mutex -> input_mutex -> dev->mutex -> ff->mutex`) that could lead to deadlock.

Here is the patch:
 	struct mutex		mutex;
 	enum uinput_state	state;
+	spinlock_t		state_lock;
 	wait_queue_head_t	waitq;
 	unsigned char		ready;

 static int uinput_request_send(struct uinput_device *udev,
 			       struct uinput_request *request)
 {
-	int retval;
+	int retval = 0;

-	retval = mutex_lock_interruptible(&udev->mutex);
-	if (retval)
-		return retval;
+	spin_lock(&udev->state_lock);

 	if (udev->state != UIST_CREATED) {
 		retval = -ENODEV;
 		goto out;
 	}

-	init_completion(&request->done);
-
 	/*
 	 * Tell our userspace application about this new request
 	 * by queueing an input event.
 	 */
 	uinput_dev_event(udev->dev, EV_UINPUT, request->code, request->id);

  out:
-	mutex_unlock(&udev->mutex);
+	spin_unlock(&udev->state_lock);
 	return retval;
 }

 static int uinput_request_submit(struct uinput_device *udev,
 				 struct uinput_request *request)
 {
 	int retval;

+	/*
+	 * Initialize completion before allocating the request slot.
+	 * Once the slot is allocated, uinput_flush_requests() may
+	 * complete it at any time, so it must be initialized first.
+	 */
+	init_completion(&request->done);
+
 	retval = uinput_request_reserve_slot(udev, request);
 	if (retval)
 		return retval;

 	retval = uinput_request_send(udev, request);
 	if (retval)
 		goto out;

 	if (!wait_for_completion_timeout(&request->done, 30 * HZ)) {
 		retval = -ETIMEDOUT;
 		goto out;
 	}

 	retval = request->retval;

  out:
 	uinput_request_release_slot(udev, request->id);
 	return retval;
 }


 static void uinput_destroy_device(struct uinput_device *udev)
 {
 	const char *name, *phys;
 	struct input_dev *dev = udev->dev;
 	enum uinput_state old_state = udev->state;

+	/*
+	 * Update state under state_lock so that concurrent
+	 * uinput_request_send() sees the state change before we
+	 * flush pending requests and tear down the device.
+	 */
+	spin_lock(&udev->state_lock);
 	udev->state = UIST_NEW_DEVICE;
+	spin_unlock(&udev->state_lock);

 	if (dev) {
 		name = dev->name;
 		phys = dev->phys;
 		if (old_state == UIST_CREATED) {
 			uinput_flush_requests(udev);
 			input_unregister_device(dev);
 		} else {
 			input_free_device(dev);
 		}
 		kfree(name);
 		kfree(phys);
 		udev->dev = NULL;
 	}
 }

 static int uinput_create_device(struct uinput_device *udev)
 {
 	struct input_dev *dev = udev->dev;
 	int error, nslot;

 	if (udev->state != UIST_SETUP_COMPLETE) {
 		printk(KERN_DEBUG "%s: write device info first\n", UINPUT_NAME);
 		return -EINVAL;
 	}

 	if (test_bit(EV_ABS, dev->evbit)) {
 		input_alloc_absinfo(dev);
 		if (!dev->absinfo) {
 			error = -EINVAL;
 			goto fail1;
 		}

 		if (test_bit(ABS_MT_SLOT, dev->absbit)) {
 			nslot = input_abs_get_max(dev, ABS_MT_SLOT) + 1;
 			error = input_mt_init_slots(dev, nslot, 0);
 			if (error)
 				goto fail1;
 		} else if (test_bit(ABS_MT_POSITION_X, dev->absbit)) {
 			input_set_events_per_packet(dev, 60);
 		}
 	}

 	if (test_bit(EV_FF, dev->evbit) && !udev->ff_effects_max) {
 		printk(KERN_DEBUG "%s: ff_effects_max should be non-zero when FF_BIT is set\n",
 			UINPUT_NAME);
 		error = -EINVAL;
 		goto fail1;
 	}

 	if (udev->ff_effects_max) {
 		error = input_ff_create(dev, udev->ff_effects_max);
 		if (error)
 			goto fail1;

 		dev->ff->upload = uinput_dev_upload_effect;
 		dev->ff->erase = uinput_dev_erase_effect;
 		dev->ff->playback = uinput_dev_playback;
 		dev->ff->set_gain = uinput_dev_set_gain;
 		dev->ff->set_autocenter = uinput_dev_set_autocenter;
 		/*
 		 * The standard input_ff_flush() implementation does
 		 * not quite work for uinput as we can't reasonably
 		 * handle FF requests during device teardown.
 		 */
 		dev->flush = uinput_dev_flush;
 	}

 	dev->event = uinput_dev_event;

 	input_set_drvdata(udev->dev, udev);

 	error = input_register_device(udev->dev);
 	if (error)
 		goto fail2;

+	spin_lock(&udev->state_lock);
 	udev->state = UIST_CREATED;
+	spin_unlock(&udev->state_lock);

 	return 0;

  fail2:	input_ff_destroy(dev);
  fail1: uinput_destroy_device(udev);
 	return error;
 }

 static int uinput_open(struct inode *inode, struct file *file)
 {
 	struct uinput_device *newdev;

 	newdev = kzalloc(sizeof(*newdev), GFP_KERNEL);
 	if (!newdev)
 		return -ENOMEM;

 	mutex_init(&newdev->mutex);
+	spin_lock_init(&newdev->state_lock);
 	spin_lock_init(&newdev->requests_lock);
 	init_waitqueue_head(&newdev->requests_waitq);
 	init_waitqueue_head(&newdev->waitq);
 	newdev->state = UIST_NEW_DEVICE;

 	file->private_data = newdev;
 	stream_open(inode, file);

 	return 0;
 }



